const DEBUG_CATEGORIES={syntax:'Syntax & indentation',runtime:'Runtime errors',logic:'Control flow & returns',units:'Units & engineering',state:'Mutable data & state',testing:'Tests & numerical checks',validation:'Input validation',objects:'Objects & methods'};
let debugPage=0;
let debugCategory='all',debugSource='all',debugStatus='all',debugSearch='';
function filteredDebugCases(){const term=debugSearch.toLowerCase().trim();return DEBUG_CASES.filter(e=>{const r=state.records[e.id];return (debugCategory==='all'||e.category===debugCategory)&&(debugSource==='all'||e.id.startsWith('debug-'+debugSource+'-'))&&(debugStatus==='all'||debugStatus==='new'&&!r||debugStatus==='missed'&&r&&!r.latestCorrect||debugStatus==='solved'&&r?.latestCorrect)&&(!term||[e.name,e.task,e.source,e.buggy,e.explanation].join(' ').toLowerCase().includes(term));});}
function debugCard(e){const r=state.records[e.id];return `<article class="program-card"><div class="card-top"><span class="tag">${esc(e.source)}</span><span class="tag">${esc(e.level)}</span></div><h3>${esc(e.name)}</h3><p>${esc(DEBUG_CATEGORIES[e.category])}</p><div class="card-bottom"><span>${r?.latestCorrect?'✓ Repaired':r?'↻ Try again':state.revealed.includes(e.id)?'Solution viewed':'Find · Repair · Retest'}</span><button class="text-button" data-debug="${e.id}">Open exercise →</button></div></article>`;}
function renderDebugList(){const list=filteredDebugCases();debugPage=Math.min(debugPage,Math.max(0,Math.ceil(list.length/PAGE_SIZE)-1));document.getElementById('debug-grid').innerHTML=list.length?list.slice(debugPage*PAGE_SIZE,(debugPage+1)*PAGE_SIZE).map(debugCard).join(''):'<p class="empty">No debugging exercises match. Clear a filter or try another search.</p>';document.getElementById('debug-count').textContent=`${list.length} exercises`;const controls=pageControls(debugPage,list.length,'debug').replace('examples</span>','exercises</span>');document.getElementById('debug-pagination-top').innerHTML=controls;document.getElementById('debug-pagination-bottom').innerHTML=controls;}
function debuggingHome(){const solved=DEBUG_CASES.filter(e=>state.records[e.id]?.latestCorrect).length;paint(`<div class="intro"><span class="eyebrow">DEBUGGING LAB · COURSE PRACTICE</span><h1>Find the cause. Make the repair.</h1><p>${DEBUG_CASES.length} exercises: 60 adapted from the course debugging guide and Week 7–8 reading notes, plus 40 original practice exercises. Inspect the faulty program, repair it, and use the regression checks to explain why the repair works.</p></div><section class="collection-banner"><div><h2>${solved} / ${DEBUG_CASES.length} repaired this session</h2><p>Forty guide examples, twelve Week 7 activities, eight Week 8 extensions, and forty new practice exercises.</p></div><button class="secondary" id="debug-random">Choose an exercise for me →</button></section><div class="filter-bar" aria-label="Debugging category"><button class="chip ${debugCategory==='all'?'active':''}" data-debug-category="all" aria-pressed="${debugCategory==='all'}">All bugs</button>${Object.entries(DEBUG_CATEGORIES).map(([id,label])=>`<button class="chip ${debugCategory===id?'active':''}" data-debug-category="${id}" aria-pressed="${debugCategory===id}">${label}</button>`).join('')}</div><div class="program-toolbar"><label class="search"><input id="debug-search" type="search" value="${esc(debugSearch)}" placeholder="Find an error, topic, or exercise…" aria-label="Search debugging exercises"></label><label class="topic-select">Source <select id="debug-source">${[['all','All sources'],['b','Debugging guide'],['w7','Week 7'],['w8','Week 8'],['new','New practice · 40']].map(([id,label])=>`<option value="${id}" ${debugSource===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="topic-select">Progress <select id="debug-status">${[['all','All exercises'],['new','Not attempted'],['missed','Needs another try'],['solved','Repaired']].map(([id,label])=>`<option value="${id}" ${debugStatus===id?'selected':''}>${label}</option>`).join('')}</select></label><button class="text-button" id="debug-clear-filters">Clear filters</button><span class="muted" id="debug-count" role="status"></span></div><div id="debug-pagination-top"></div><div class="program-grid" id="debug-grid"></div><div id="debug-pagination-bottom"></div><p class="code-info">The browser provides a guided repair check. It compares your code with known repairs; it does not run Python or evaluate arbitrary solutions. Run the supplied checks in your Python environment for execution feedback. Inputs and classroom engineering limits are illustrative.</p>`,'debugging');renderDebugList();}
// A small lexical comparison retains names, string contents, and indentation
// structure while allowing comments, quote style, spacing, and indent width.
function normalizeRepair(code){const lines=String(code).replace(/\r\n?/g,'\n').split('\n'),indents=[0],result=[];for(const raw of lines){const expanded=raw.replace(/^\t+/,m=>' '.repeat(m.length*4));const indent=expanded.match(/^ */)[0].length;const text=expanded.slice(indent);let tokens=[],i=0;while(i<text.length){const c=text[i];if(/\s/.test(c)){i++;continue;}if(c==='#')break;if(c==='"'||c==="'"){const quote=c;let value='',closed=false;i++;while(i<text.length){if(text[i]==='\\'&&i+1<text.length){value+=text[i]+text[i+1];i+=2;}else if(text[i]===quote){i++;closed=true;break;}else value+=text[i++];}if(!closed)return null;tokens.push(['string',value]);continue;}let match=text.slice(i).match(/^[A-Za-z_][A-Za-z_0-9]*/);if(match){tokens.push(['name',match[0]]);i+=match[0].length;continue;}match=text.slice(i).match(/^(?:\d[\d_]*(?:\.\d[\d_]*)?|\.\d[\d_]*)(?:[eE][+-]?\d[\d_]*)?/);if(match){tokens.push(['number',match[0].replace(/_/g,'')]);i+=match[0].length;continue;}match=text.slice(i).match(/^(?:\*\*|\/\/|==|!=|<=|>=|\+=|-=|\*=|\/=|%=|:=|->|[+\-*\/%=<>:.,()[\]{};@])/);if(match){tokens.push(['op',match[0]]);i+=match[0].length;continue;}return null;}if(!tokens.length)continue;if(indent>indents[indents.length-1])indents.push(indent);else while(indent<indents[indents.length-1])indents.pop();if(indent!==indents[indents.length-1])return null;result.push([indents.length-1,tokens]);}return result.length?JSON.stringify(result):null;}
function stashDebugDraft(id){const text=document.getElementById('debug-editor').value;state.debugDrafts=state.debugDrafts||{};state.debugDrafts[id]=text;save();return text;}
function debugExercise(id,feedback=null){const e=DEBUG_CASES.find(e=>e.id===id);if(!e){debuggingHome();return;}const draft=state.debugDrafts?.[id]??e.buggy;const shown=feedback==='shown'||feedback==='right';const next=DEBUG_CASES[(DEBUG_CASES.indexOf(e)+1)%DEBUG_CASES.length];const observed=e.observed.error;const label=observed.type==='StepLimit'?'Repeated execution did not finish in the bounded verification run.':observed.type==='OutputMismatch'?'The printed result differs from the stated expected result.':observed.type==='AssertionError'?'The faulty program fails a regression expectation.':`${observed.type}: ${observed.message}`;paint(`<button class="back-button" data-nav="debugging">← All debugging exercises</button><div class="debug-layout"><section class="question-card"><div class="question-label"><span>${esc(e.source)}</span><span>${esc(e.level)}</span></div><h1>${esc(e.name)}</h1><p>${esc(e.task)}</p><span class="tag">${esc(DEBUG_CATEGORIES[e.category])}</span><details class="hint observed-error"><summary>Observe the faulty version</summary><p>${esc(label)}</p>${e.observed.output?`<pre><code>${esc(e.observed.output.slice(0,1300))}${e.observed.output.length>1300?'\n… output truncated':''}</code></pre>`:''}<p class="code-info">This observation comes from checking the original faulty program and its regression cases in Python. Unbounded loops and recursion were stopped after a fixed number of steps.</p></details><label class="field-label" for="debug-editor">Your repair</label><p class="code-info">Edit the complete program below. Keep the task’s variables and approach. Spacing, comments, quote style, and consistent indent width may differ from the reference.</p><textarea id="debug-editor" data-id="${e.id}" class="code-input debug-editor" spellcheck="false" autocapitalize="off" autocomplete="off" wrap="off">${esc(draft)}</textarea><div class="actions"><button class="primary" id="check-repair" data-id="${e.id}">Check my repair →</button><button class="secondary" id="reveal-repair" data-id="${e.id}">Show worked repair</button><button class="text-button" id="reset-repair" data-id="${e.id}">Restore faulty code</button></div>${feedback?`<div class="feedback ${feedback==='wrong'?'incorrect':''}" role="status"><h3>${feedback==='right'?'✓ Your code matches a verified repair.':feedback==='shown'?'A worked repair':feedback==='empty'?'Write a repair first.':'This differs from the guided repair.'}</h3>${shown?`<p>${esc(e.explanation)}</p><pre><code>${esc(e.solutions[0])}</code></pre>${e.referenceOutput?`<h3>Verified printed output</h3><pre><code>${esc(e.referenceOutput)}</code></pre>`:'<p>The reference completes its regression checks without an exception.</p>'}${feedback==='shown'?'<p>Viewing the repair does not mark the exercise as solved.</p>':''}`:feedback==='wrong'?'<p>Check the stated behavior, names, units, and block structure. Another valid Python solution may differ from this guided checker; use the regression checks in Python to evaluate it.</p>':'<p>Use the faulty program, task, and hint to make a repair.</p>'}</div>`:''}<details class="hint"><summary>Get a hint</summary><p>${esc(e.hint)}</p></details><details class="hint" open><summary>Regression checks to run in Python</summary><p class="code-info">Append these checks after your repaired program. Also compare any printed output with the task. Keep them for future changes.</p><pre><code>${esc(e.tests)}</code></pre></details><div class="actions"><button class="secondary" data-debug="${next.id}">Next exercise →</button><button class="text-button" data-nav="session">View session progress</button></div><p class="code-info">${e.id.startsWith('debug-new-')?'Original practice exercise with self-contained setup and independently stated regression expectations.':'Adapted from the earlier course material with self-contained setup and selected test fixtures. Week 8 object exercises are labeled as extensions.'} The browser does not execute your program.</p></section><aside class="debug-aside panel"><h3>A repair worth keeping</h3><ol><li>State the expected behavior.</li><li>Find a small failing case.</li><li>Trace where values first go wrong.</li><li>Repair the cause.</li><li>Run typical, boundary, and invalid-input checks.</li></ol><p class="muted">A script can run and still be wrong. Check units, state preservation, and what the function returns.</p></aside></div>`,'debugging',!feedback);}
function checkRepair(id){const e=DEBUG_CASES.find(e=>e.id===id);const draft=stashDebugDraft(id);if(!draft.trim()){debugExercise(id,'empty');return;}const value=normalizeRepair(draft);const right=value!==null&&e.solutions.some(s=>normalizeRepair(s)===value);record(e,right,'debug');debugExercise(id,right?'right':'wrong');}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.debugPage!==undefined){debugPage=Number(b.dataset.debugPage);renderDebugList();}else if(b.dataset.debug)nav('debug/'+b.dataset.debug);else if(b.dataset.debugCategory){debugPage=0;debugCategory=b.dataset.debugCategory;debuggingHome();}else if(b.id==='debug-clear-filters'){debugPage=0;debugCategory=debugSource=debugStatus='all';debugSearch='';debuggingHome();}else if(b.id==='debug-random'){const list=filteredDebugCases();if(list.length)nav('debug/'+list[Math.floor(Math.random()*list.length)].id);}else if(b.id==='check-repair')checkRepair(b.dataset.id);else if(b.id==='reveal-repair'){stashDebugDraft(b.dataset.id);if(!state.revealed.includes(b.dataset.id))state.revealed.push(b.dataset.id);save();debugExercise(b.dataset.id,'shown');}else if(b.id==='reset-repair'){state.debugDrafts=state.debugDrafts||{};delete state.debugDrafts[b.dataset.id];save();debugExercise(b.dataset.id);}});
document.addEventListener('input',event=>{if(event.target.id==='debug-search'){debugPage=0;debugSearch=event.target.value;renderDebugList();}else if(event.target.id==='debug-editor'){state.debugDrafts=state.debugDrafts||{};state.debugDrafts[event.target.dataset.id]=event.target.value;save();}});
document.addEventListener('change',event=>{if(event.target.id==='debug-source'){debugPage=0;debugSource=event.target.value;renderDebugList();}else if(event.target.id==='debug-status'){debugPage=0;debugStatus=event.target.value;renderDebugList();}});
